'use strict';
// Appointment evidence and application planning share the atlas's source records.
function careerStatus(v){return String(v||'not reviewed').replaceAll('_',' ')}
function careerSources(items){return `<ul class="career-sources">${arr(items).map(s=>typeof s==='string'?`<li>${ext(s,'Source')}</li>`:`<li>${ext(s.url,s.label||'Source')}<p class="small">${esc(s.evidence||s.supports||'')}</p></li>`).join('')}</ul>`}
function careerYear(v){return v?.year?String(v.year):'Unknown'}
function careerEvidence(x){const c=x.career||{};return Boolean(c.first_faculty?.year||c.current_institution?.year)}
function applicationSignals(x){return arr(x.environment?.evidence).length>0||['internship','visiting_research','graduate'].some(k=>arr(x.opportunities?.[k]?.sources).length>0)}
function universityPrograms(){const g=A.application_guide||{};return `<section class="section"><div class="section-heading"><h2>University research programs</h2><p>These are separately published entry routes. Eligibility and participating labs matter as much as dates.</p></div><div class="guide-columns">${arr(g.university_programs).map(p=>`<article><h3>${esc(p.name)}</h3><p class="small">${esc(careerStatus(p.status))} · checked ${esc(p.checked)}</p><p>${esc(p.summary)}</p>${ext(p.url,'Official program and eligibility')}</article>`).join('')}</div><details class="career-audit"><summary>What each evidence type can establish</summary><div class="table-scroll"><table><thead><tr><th>Source type</th><th>What it establishes</th><th>Limits</th></tr></thead><tbody>${arr(g.evidence_types).map(e=>`<tr><td>${esc(e.type)}</td><td>${esc(e.can_establish)}</td><td>${esc(e.cannot_establish)}</td></tr>`).join('')}</tbody></table></div></details></section>`}
function careerCell(v){return `<strong class="year-value ${v?.year?'':'unknown'}">${careerYear(v)}</strong>${v?.year?`<span>${esc(v.role||'Faculty')}</span><span class="small">${esc(v.institution||'')}</span>${/conflict|disput|self.assert/i.test(v.status||'')?`<span class="tag">${esc(careerStatus(v.status))}</span>`:''}`:`<span class="small">${esc(careerStatus(v?.status||'not established'))}</span>`}`}
function appointmentPanel(x,compact=false){const c=x.career||{},audit=x.career_audit||{};return `<section class="career-panel${compact?' compact':''}" aria-label="Faculty appointment history"><h2>When this research career began</h2><p class="small">Earliest documented regular faculty service and the current institutional appointment are separate dates. Research, PI and affiliated roles retain their original titles. They do not measure mentoring quality or current capacity.</p><div class="career-milestones">${[['first_faculty','Earliest faculty appointment'],['current_institution','Current faculty / PI appointment'],['full_professor','Documented full-professor role']].map(([k,label])=>`<div><h3>${label}</h3>${careerCell(c[k])}${c[k]?.date?`<span class="small">${esc(c[k].date)} · ${esc(c[k].precision||'')}</span>`:''}${arr(c[k]?.sources).length?`<details><summary>Evidence</summary>${careerSources(c[k].sources)}</details>`:''}</div>`).join('')}</div>${arr(c.notes).length?`<ul class="career-notes">${c.notes.map(n=>`<li>${esc(typeof n==='string'?n:plain(n))}</li>`).join('')}</ul>`:''}${arr(c.timeline).length?`<details><summary>Additional career chronology</summary><ul>${c.timeline.map(t=>`<li>${esc(typeof t==='string'?t:[t.start_date||t.start_year||t.date||t.year,t.end_date||t.end_year,t.role,t.institution,t.summary||t.note].filter(Boolean).join(' · '))}${typeof t==='object'?careerSources(t.sources||(t.source_url?[{url:t.source_url,label:'Chronology source'}]:[])):''}</li>`).join('')}</ul></details>`:''}<details class="career-audit"><summary>Appointment check · ${esc(careerStatus(audit.status))}</summary><p>${esc(audit.reason||'Appointment-specific review has not been completed.')}</p><p class="small">${esc(c.reviewed_on||audit.reviewed_on||'')}</p>${careerSources(audit.sources)}</details></section>`}
function opportunityDetail(o,label){o=o||{};return `<article class="opportunity-route"><h3>${label}</h3><span class="tag">${esc(careerStatus(o.status||'not verified'))}</span><p>${esc(o.summary||'No specific current opportunity has been verified. Use the official route and confirm eligibility, supervision and funding.')}</p>${o.deadline?`<p>Deadline: ${esc(plain(o.deadline))}</p>`:''}${o.checked?`<p class="small">Checked ${esc(o.checked)}</p>`:''}${careerSources(o.sources)}</article>`}
function applicationPanel(x){const o=x.opportunities||{},e=x.environment||{},audit=x.environment_audit||{},ev=arr(e.evidence);return `<section class="application-panel" id="research-entry"><h2>Joining this lab</h2><p class="small">A recruitment page may describe a standing process or a past cycle. Check its date and any deadline before applying.</p><div class="opportunity-routes">${opportunityDetail(o.internship,'Undergraduate internship')}${opportunityDetail(o.visiting_research,'Visiting research')}${opportunityDetail(o.graduate,'Graduate study')}</div>${['application_route','eligibility','funding','deadline'].filter(k=>o[k]).map(k=>`<p><strong>${esc(careerStatus(k))}:</strong> ${esc(typeof o[k]==='string'?o[k]:plain(o[k]))}</p>`).join('')}<h2>Lab environment: what the sources say</h2><p>${esc(e.summary||'A lab-specific environment review is not yet available. The absence of public accounts does not establish a good or bad environment.')}</p>${ev.length?`<div class="environment-evidence">${ev.map(v=>`<article><div class="evidence-context"><span>${esc(careerStatus(v.source_type))}</span><span>${esc(v.date||'Source date not stated')}</span></div><h3>${esc(careerStatus(v.dimension||'Documented observation'))}</h3><p>${esc(v.claim||'')}</p><p class="small">${esc(v.evidence_strength||'Read in the context of the named source and date.')}</p>${ext(v.url,v.label||'Read the source')}</article>`).join('')}</div>`:''}<p class="notice">Lab-written values describe intended practice. A named student account reflects that person’s experience and time period. An alumni destination shows an outcome; it does not by itself establish supervision quality, workload or wellbeing.</p>${arr(e.unknowns).length?`<h3>Still unknown</h3><ul>${e.unknowns.map(t=>`<li>${esc(plain(t))}</li>`).join('')}</ul>`:''}${arr(e.questions_for_students).length?`<h3>Questions to ask current students</h3><ul>${e.questions_for_students.map(t=>`<li>${esc(plain(t))}</li>`).join('')}</ul>`:''}<details class="career-audit"><summary>Environment and recruitment check · ${esc(careerStatus(audit.status))}</summary><p>${esc(audit.reason||'This profile has not yet had a dedicated student/alumni and recruitment review.')}</p>${careerSources(audit.sources)}</details><p><a href="#/applications">Compare research-entry routes and appointment years</a></p></section>`}
function applicationGuide(){return `<section class="section application-guide"><div class="section-heading"><h2>Turn a shortlist<br>into useful conversations.</h2><p>A professor’s start year helps you understand the group’s stage. The questions below help establish whether the actual project and supervision fit you.</p></div><div class="guide-columns"><div><h3>Before contacting a lab</h3><ol><li>Read two recent papers. Write one specific research question or experiment you could pursue.</li><li>Identify the entry route: external undergraduate internship, visiting researcher, thesis project or degree admission.</li><li>Check whether the PI is current, incoming, on leave or historical. Ask who can supervise during your intended dates.</li><li>Prepare a short project portfolio, relevant coursework, availability and a realistic weekly commitment.</li></ol></div><div><h3>Ask current students and recent alumni</h3><ul><li>Who meets with a new intern each week, and how often does the PI give feedback?</li><li>How are project scope, authorship and ownership decided when results change?</li><li>What does an ordinary week look like? Are hours and time away flexible?</li><li>What funding, workspace, computing and hardware access are confirmed?</li><li>How are stalled projects, disagreements and changes of advisor handled?</li><li>What happened to the last few interns, including those who did not publish or stay?</li></ul></div><div><h3>Read environment evidence carefully</h3><p>Look for specific, dated experiences across several people and career stages. Institutional interviews can contain direct student voices but are edited selections. Lab handbooks state expectations; independent accounts help show how those expectations work in practice.</p><p>Prestige, citations, visible social events and alumni jobs do not settle lab culture. This atlas does not assign a reputation score.</p><p>New groups may be building infrastructure; established groups may delegate supervision. Neither predicts your experience without asking.</p></div></div></section>`}
function applicationsPage(){const f=filters.applications,n=A.career_sweep||{};return `<div class="wrap">${head('Find your way<br>into a research lab.','Compare when faculty began, when they started their current institutional role, and what is documented about joining their groups. Start with research fit, then inspect the sources and supervision arrangements.',`<div class="actions"><a class="text-link" href="#/scholars">Explore research fit and papers</a><a class="text-link" href="downloads/graduate-research-atlas.xlsx">Download the application workbook</a><a class="text-link" href="downloads/career-coverage-report.json">Every appointment-source check</a></div>`)}<div class="application-intro"><p><strong>${n.individual_first_faculty_year||n.first_faculty_year||0} / ${n.individual_researchers||A.labs.length}</strong> researchers have a documented earliest faculty year.</p><p><strong>${n.individual_current_institution_year||n.current_institution_year||0} / ${n.individual_researchers||A.labs.length}</strong> have a documented current institutional appointment.</p><p><strong>${n.environment_evidence_profiles||0} / ${A.labs.length}</strong> have lab-specific environment evidence.</p></div><div class="filters application-filters" data-filter-group="applications"><label class="search-field">Scholar, lab or university<input data-filter="q" value="${esc(f.q)}" placeholder="Youngwoon Lee, navigation, KAIST…"></label><label>Region<select data-filter="region">${[['','All regions'],['Korea','Korea'],['US','United States'],['Europe','Europe']].map(([v,l])=>option(v,l,f.region)).join('')}</select></label><label>Research field<select data-filter="chapter">${chapterOptions(f.chapter)}</select></label><label>Year to compare<select data-filter="yearKind">${[['first_faculty','Earliest faculty year'],['current_institution','Current institutional appointment']].map(([v,l])=>option(v,l,f.yearKind||'first_faculty')).join('')}</select></label><label>From year<input data-filter="min" type="number" min="1940" max="2035" value="${esc(f.min)}" placeholder="e.g. 2020"></label><label>Through year<input data-filter="max" type="number" min="1940" max="2035" value="${esc(f.max)}" placeholder="e.g. 2026"></label><label>Evidence<select data-filter="evidence">${[['','All evidence states'],['dates','At least one appointment date'],['unknown','Missing one or both appointment dates'],['environment','Lab environment evidence'],['student','Student or alumni sources'],['experience','Student experience / acknowledgments'],['internship','Internship source attached'],['graduate','Graduate-entry source attached']].map(([v,l])=>option(v,l,f.evidence)).join('')}</select></label><label>Sort<select data-filter="sort">${[['','Professor name'],['first-new','Newest first faculty year'],['arrival-new','Newest faculty arrival']].map(([v,l])=>option(v,l,f.sort)).join('')}</select></label><button data-clear="applications">Reset</button></div><p class="small">Year ranges exclude unknown dates. Current institutional appointments can include explicitly labeled research, PI or affiliated roles; inspect the role before comparing. “Earliest documented” is the first faculty appointment found in the reviewed chronology, which may be incomplete. The table separates individual professors in shared group records. Their profile link and shortlist entry lead to the shared lab page.</p><div id="applicationResults" aria-live="polite">${applicationResults()}</div>${universityPrograms()}${applicationGuide()}</div>`}
function applicationResults(){const f=filters.applications,key=f.yearKind||'first_faculty',tokens=normal(f.q).split(/\s+/).filter(Boolean);let records=A.labs.flatMap(x=>x.members?.length?x.members.map(m=>({...x,professor:m.name||m.professor,career:m.career||{first_faculty:{},current_institution:{},full_professor:{}},career_audit:m.career_audit||{},shared_group:true})):[x]);let xs=records.filter(x=>{const c=x.career||{},v=c[key]?.year,e=arr(x.environment?.evidence),text=normal([x.professor,x.university,x.lab,x.department,...arr(x.topics)].join(' '));return tokens.every(t=>text.includes(t))&&(!f.region||x.region===f.region)&&(!f.chapter||x.chapter_ids.includes(f.chapter))&&(!f.min||(v!=null&&v>=Number(f.min)))&&(!f.max||(v!=null&&v<=Number(f.max)))&&(!f.evidence||(f.evidence==='dates'?careerEvidence(x):f.evidence==='unknown'?(!c.first_faculty?.year||!c.current_institution?.year):f.evidence==='environment'?e.length>0:f.evidence==='student'?e.some(v=>/student|alumnus|alumna/i.test(v.source_type||'')):f.evidence==='experience'?e.some(v=>/first_person_account|thesis_acknowledgments|student_interview/i.test(v.source_type||'')):arr(x.opportunities?.[f.evidence]?.sources).length>0))});xs.sort((a,b)=>f.sort==='first-new'?(b.career.first_faculty.year||0)-(a.career.first_faculty.year||0)||a.professor.localeCompare(b.professor):f.sort==='arrival-new'?(b.career.current_institution.year||0)-(a.career.current_institution.year||0)||a.professor.localeCompare(b.professor):a.professor.localeCompare(b.professor));pages.applications=Math.max(1,Math.min(pages.applications,Math.ceil(xs.length/24)||1));return `<p class="result-count">${xs.length} matching researcher rows · snapshot 29 October 2026</p>${xs.length?`<div class="table-scroll"><table class="application-table"><thead><tr><th>Professor and lab</th><th>Earliest faculty role</th><th>Current institutional appointment</th><th>Research-entry evidence</th><th>Shortlist</th></tr></thead><tbody>${xs.slice((pages.applications-1)*24,pages.applications*24).map(x=>`<tr><td><a class="scholar-name" href="${url('scholar',x.id)}">${esc(x.professor)}</a><p>${esc(x.university)}</p><p class="small">${esc(x.lab)}</p>${x.shared_group?'<span class="tag">Shared group profile</span>':''}${x.historical||x.incoming?`<span class="tag warn">${x.historical?'Historical / unavailable':'Incoming appointment'}</span>`:''}</td><td>${careerCell(x.career.first_faculty)}</td><td>${careerCell(x.career.current_institution)}</td><td>${applicationSignals(x)?`${arr(x.environment?.evidence).length?`<p>${arr(x.environment.evidence).length} environment source observations</p>`:''}${['internship','visiting_research','graduate'].filter(k=>arr(x.opportunities?.[k]?.sources).length).map(k=>`<p class="small">${esc(careerStatus(k))}: ${esc(careerStatus(x.opportunities[k].status))}</p>`).join('')}<a href="${url('scholar',x.id)}">Read evidence and conditions</a>`:`<span class="small">${x.environment_audit?.status==='not_reviewed'?'Dedicated review pending':'No specific opportunity established in reviewed sources'}</span>`}</td><td>${saveButton('scholar',x.id,'Save')}</td></tr>`).join('')}</tbody></table></div>${paginate('applications',xs.length)}`:empty('No matching records','Widen the year range or reset the evidence filter. Unknown appointment years are excluded from numerical ranges.')}`}
